namespace Schemorph.Provider.Postgres;

/// <summary>
/// The catalog as Schemorph reads it — plain data, no engine types, no
/// connection. Everything downstream of the reader works on this, which is what
/// keeps rendering testable without a database.
/// </summary>
/// <summary>How a column's value is generated by the engine, if at all.</summary>
public enum PgIdentity
{
    None,
    /// <summary>GENERATED ALWAYS AS IDENTITY.</summary>
    Always,
    /// <summary>GENERATED BY DEFAULT AS IDENTITY.</summary>
    ByDefault,
}

/// <param name="DataType">
/// The engine's own rendering (<c>format_type</c>), not a mapping of ours. The
/// engine is the normalizer (ADR-0007); re-spelling types here would reintroduce
/// exactly the text-comparison drift that decision exists to avoid.
/// </param>
/// <param name="Default">
/// Plain DEFAULT expression (<c>pg_get_expr</c>). Null for generated columns —
/// the catalog stores their expression in the same slot, but rendering it as
/// DEFAULT would be wrong SQL, so the reader routes it to
/// <paramref name="GeneratedAs"/> instead.
/// </param>
/// <param name="GeneratedAs">
/// The generation expression of a <c>GENERATED ALWAYS AS (…)</c> column —
/// stored or, on PostgreSQL 18 and later, virtual (<paramref name="GeneratedKind"/>).
/// </param>
/// <param name="IdentityOptions">
/// Sequence options of an identity column, already rendered (e.g.
/// <c>START WITH 100 INCREMENT BY 5</c>) — null when every option is the
/// engine default, so the common case renders clean.
/// </param>
/// <param name="GeneratedKind">
/// Whether a generated column's value is stored on disk or computed when read.
/// Meaningful only when <paramref name="GeneratedAs"/> is set. A column of the
/// other kind is a different column — there is no in-place conversion — so the
/// kind takes part in equality like the expression does.
/// </param>
public sealed record PgColumn(
    string Name,
    string DataType,
    bool NotNull,
    string? Default,
    PgIdentity Identity = PgIdentity.None,
    string? GeneratedAs = null,
    string? IdentityOptions = null,
    PgGeneratedKind GeneratedKind = PgGeneratedKind.Stored);

/// <summary>How a generated column keeps its value.</summary>
public enum PgGeneratedKind
{
    /// <summary><c>STORED</c> — computed on write and kept in the row (PostgreSQL 12 and later).</summary>
    Stored,
    /// <summary><c>VIRTUAL</c> — computed when read, nothing kept (PostgreSQL 18 and later, where it is the default).</summary>
    Virtual,
}

/// <param name="Definition">
/// From <c>pg_get_constraintdef</c> — the engine's canonical form, e.g.
/// <c>PRIMARY KEY ("Id")</c>. Emitted verbatim for the same reason.
/// </param>
public sealed record PgConstraint(string Name, string Definition);

/// <param name="Definition">
/// From <c>pg_get_indexdef(oid)</c> — a complete CREATE INDEX statement, taken
/// whole for the same reason a constraint's definition is: it is the engine's
/// own canonical form, so every aspect it distinguishes stays distinguished
/// without a parser in the comparison layer.
///
/// One substitution makes it comparable across schemas. Unlike the other
/// renderings, this one qualifies the table unconditionally — search_path does
/// not unqualify it (measured 2026-07-22, re-measured 2026-07-30) — so
/// comparison mode removes that qualifier and inspect keeps it.
///
/// The alternative, a per-column projection from
/// <c>pg_get_indexdef(oid, n, …)</c>, was measured and is not sufficient: that
/// form renders a key as the bare column or expression and carries no sort
/// direction, NULLS placement, operator class or collation, whatever the pretty
/// flag says. Two indexes differing only there answer different queries, and a
/// comparison built on it calls them equal.
/// </param>
/// <param name="IsValid">
/// <c>pg_index.indisvalid</c>. A concurrent index build that fails part-way leaves its index
/// behind, <em>invalid</em>: the definition reads exactly like a good one, but the engine neither
/// uses it for queries nor (for a unique index) enforces it. It takes part in equality, so a live
/// invalid index differs from the valid one the desired state declares and the plan rebuilds it
/// rather than reporting the schema in sync.
/// </param>
public sealed record PgIndex(string Name, string Definition, bool IsValid = true);

public sealed record PgTable(
    string Schema,
    string Name,
    IReadOnlyList<PgColumn> Columns,
    IReadOnlyList<PgConstraint> Constraints,
    IReadOnlyList<PgIndex> Indexes);
